return-response.set-body:
@{
                        return new JObject(
                            new JProperty("error", "claude_unavailable"),
                            new JProperty("message", "Claude API is temporarily unavailable"),
                            new JProperty("retry_after", 30),
                            new JProperty("correlationId", context.Variables.GetValueOrDefault("correlationId", "")),
                            new JProperty("timestamp", DateTime.UtcNow.ToString("o"))
                        ).ToString();
                    }
